// We use the Verus verification framework to implement and verify
// a function that computes the maximum element of a non-empty Vec<i8>.

verus! {
    // max: returns the maximum element of a non-empty vector of i8s.
    //
    // Requirements:
    //  - The input Vec must be non-empty.
    // Guarantees:
    //  - The returned value is at least as large as every element of the vector.
    //  - The returned value is equal to some element in the vector.
    fn max(a: Vec<i8>) -> (result: i8)
        requires
            a.len() > 0,
        ensures
            // result is >= every element in a
            forall|j: usize| j < a.len() ==> result >= a[j],
        ensures
            // result equals at least one element in a
            exists|j: usize| j < a.len() && result == a[j],
    {
        // Initialize mx to the first element; vector is non-empty by require
        let mut mx: i8 = a[0];
        // We will scan the rest of the vector starting at index 1
        let mut i: usize = 1;

        // Loop invariant maintains that, up to index i (exclusive),
        // mx is the maximum of a[0..i].
        while i < a.len()
            invariant
                // i stays within [1, a.len()]
                1 <= i && i <= a.len(),
            invariant
                // For all j < i, mx >= a[j]
                forall|j: usize| j < i ==> mx >= a[j],
            invariant
                // There is some j < i with mx == a[j]
                exists|j: usize| j < i && mx == a[j],
            decreases
                // Measures progress: the remaining elements to scan
                a.len() - i,
        {
            if a[i] > mx {
                mx = a[i];
            }
            i += 1;
        }

        // After the loop, i == a.len(), so invariants give us the postconditions
        result = mx;
    }

    // A few simple tests to exercise the function
    #[verifier::test]
    fn test_max_examples() {
        assert(max(vec![3, 1, 4, 2]) == 4);
        assert(max(vec![-5, -1, -3]) == -1);
        assert(max(vec![42]) == 42);
    }
}